class MsprofLauncher(object):

    def __init__(self, is_model_: bool):
        self.is_model = is_model_
        self.utils = rt.npu_utils()
        self.start_time = 0

    def start(self):
        if self.is_model:
            return

        self.start_time = self.utils.msprof_sys_cycle_time()

    def process(self, kernel_name: str, block_num: int, task_type: int):
        if self.is_model:
            return

        time_stamp = self.utils.msprof_sys_cycle_time()
        self.utils.msprof_report_compact_info(time_stamp, kernel_name, block_num, task_type)

        end_time = self.utils.msprof_sys_cycle_time()
        self.utils.msprof_report_api(self.start_time, end_time, kernel_name)


@dataclass(frozen=True)
class LaunchOptions:
    core_num: int = 0
    stream: Optional[rt.Stream] = None


class Launcher:

    def __init__(self, options: LaunchOptions):
        self.options = options
        self.msprof = MsprofLauncher(rt.is_model())

    @staticmethod
    def get_core_num(device_id: Optional[int] = None) -> int:
        return rt.device_info(rt.DeviceModuleType.RT_MODULE_TYPE_AICORE, rt.DeviceInfoType.INFO_TYPE_CORE_NUM,
                              device_id)

    @staticmethod
    def expand_kernel_args(args: Iterable[Any]) -> List[Union[np.generic, MemoryHandle]]:
        kernel_args = []
        for arg in args:
            if isinstance(arg, int):
                kernel_args.append(np.int32(arg))
            elif isinstance(arg, float):
                kernel_args.append(np.float32(arg))
            elif isinstance(arg, bool):
                kernel_args.append(np.int8(int(arg)))
            elif isinstance(arg, np.generic):
                kernel_args.append(arg)
            elif isinstance(arg, Struct):
                kernel_args.append(resolve_memory_handle(arg.pack()))
            else:
                kernel_args.append(resolve_memory_handle(arg))
        return kernel_args

    def launch_kernel(self, function: rt.Function, kernel_args: List[Union[np.generic, MemoryHandle]],
                      enable_debug: bool, func_name: str, core_type: rt.CoreType) -> None:

        def blobs_size(inputs: List[bytes]) -> int:
            return sum(len(x) for x in input_blobs)

        input_blobs: List[bytes] = []
        memory_args: List[MemoryHandle] = []
        for arg in kernel_args:
            if isinstance(arg, np.generic):
                input_blobs.append(arg.tobytes())
                if arg.itemsize < 4:
                    input_blobs.append(b"\0" * (4 - arg.itemsize))
                elif arg.itemsize > 4 and arg.itemsize < 8:
                    input_blobs.append(b"\0" * (8 - arg.itemsize))
            elif isinstance(arg, MemoryHandle):
                if blobs_size(input_blobs) % 8 != 0:
                    input_blobs.append(b"\0" * 4)
                handle = arg.copy_to_device()
                input_blobs.append(np.uint64(handle).tobytes())
                memory_args.append(arg)
            else:
                raise TypeError(f"Unsupported kernel argument of type {type(arg)}")
        aligned_len = int(np.ceil(blobs_size(input_blobs) / 8)) * 8
        combined_inputs = bytes().join(input_blobs).ljust(aligned_len, b"\0")
        chunks = [combined_inputs[i:i + 8] for i in range(0, len(combined_inputs), 8)]
        inputs = [ctypes.c_uint64(int.from_bytes(x, "little")) for x in chunks]

        stream = self.options.stream or rt.current_stream()

        self.msprof.start()
        rt.launch_kernel(function, self.options.core_num, inputs, stream_handle=stream)
        self.msprof.process(func_name, self.options.core_num, rt.msprof_task_type(core_type))

        rt.synchronize()
        for index, arg in enumerate(memory_args):
            try:
                if enable_debug and index == len(memory_args) - 1:
                    rt.call_print_interface(inputs[-1], utils.TOTAL_DUMP_SIZE, stream, func_name)
                else:
                    arg.copy_from_device()
            finally:
                arg.release_memory()

    def run(self, kernel: CompiledKernel, function_name: str, user_args: Tuple[Any]) -> None:
        dry_run = os.environ.get('DRY_RUN')
        if dry_run:
            return
        if not isinstance(kernel.binary, bytes):
            raise RuntimeError("Compiled binary is required to launch the kernel")
        explicit_arg = iter(user_args)
        kernel_args = []
        for kind in kernel.kernel_args:
            if kind == ir.KernelArgument.Explicit:
                kernel_args.append(next(explicit_arg))
            elif kind == ir.KernelArgument.FftsAddr:
                ffts_addr = np.array([rt.c2c_ctrl_addr()], dtype=np.uint64)
                kernel_args.append(ffts_addr)
            else:
                raise ValueError(f"Unexpected KernelArgument value: {kind}")
        if kernel.enable_debug:
            kernel_args.append(np.zeros(utils.TOTAL_DUMP_SIZE, dtype=np.int8))
        kernel_args = self.expand_kernel_args(tuple(kernel_args))
        kernel_handle = rt.register_device_binary_kernel(kernel.binary, rt.magic_elf_value(kernel.core_type))
        function = rt.register_function(kernel_handle, function_name, mode=0)
        if self.options.core_num <= 0:
            raise ValueError("Core number should be large than 0")
        self.launch_kernel(function, kernel_args, kernel.enable_debug, function_name, kernel.core_type)
        rt.free_mem()

    if name:
        return name
    raise NotImplementedError(f"Method for {op_class.__name__} is not implemented")

@staticmethod
def has_builder_support(value) -> bool:
    return isinstance(value, (BaseTensor, GlobalAddress, PlainValue))

def raise_unsupported(self, node: ast.AST, message: Optional[str] = None, context: bool = False) -> NoReturn:
    error = UnsupportedSyntaxError(node, self.src, message)
    if context:
        raise error
    raise error from None

def apply_binary_method(self, method_name, lhs, rhs) -> Any:
    reverse_method_name = re.sub(r"__(.*)__", r"__r\1__", method_name)
    if not self.has_builder_support(lhs) and self.has_builder_support(rhs):
        return getattr(rhs, reverse_method_name)(lhs)
    result = getattr(lhs, method_name)(rhs)
    if result is NotImplemented:
        result = getattr(rhs, reverse_method_name)(lhs)
    return result

def get_call_args(self, func: Callable, *args: Tuple[Any], **kwargs: Dict[str, Any]) -> Dict[str, Any]:
    sig = inspect.signature(func)
    bound_args = sig.bind(*args, **kwargs)
    bound_args.apply_defaults()
    return bound_args.arguments

def call_jit_function(self, fn: Function, args: Tuple[Any], kwargs: Dict[str, Any]) -> Optional[Any]:
    base_fn = fn.fn
    call_args = self.get_call_args(base_fn, *args, **kwargs)
    annotations = get_annotations(base_fn)
    runtime_args, constexprs = Function.split_args(call_args, annotations)
    arg_values: Dict[str, IRValue] = {}
    for name, value in runtime_args.items():
        if isinstance(value, IRValue):
            arg_values[name] = value
        else:
            arg_values[name] = materialize_ir_value(value)
    arg_types = {name: IRArgType(type(value), value.to_ir().get_type()) for name, value in arg_values.items()}
    fn_name = fn.node.name
    ret_types = []
    if global_builder.get_ir_module().has_function(fn_name):
        ret_types = self.state.visited_return_types[fn_name]
    else:
        spec = Specialization(arg_types, constexprs)
        with self.visit_region():
            visitor = FunctionVisitor(fn.src, spec, base_fn.__globals__, fn.location, self.options,
                                      self.state.visited_return_types, is_kernel=False)
            visitor.visit(fn.node)
            ret_types = visitor.state.return_types
            self.state.visited_return_types[fn_name] = ret_types
    ir_operands = [value.to_ir() for value in arg_values.values()]
    op = global_builder.get_ir_builder().create_func_CallOp(fn.node.name, ir_operands,
                                                            [ret_type.ir_type for ret_type in ret_types])
    if len(ret_types) == 0:
        return None
    return_values = [ret_type.py_type.from_ir(op.get_result(i)) for i, ret_type in enumerate(ret_types)]
    if len(ret_types) == 1:
        return return_values[0]
    return return_values

def compute_inout(self, node: ast.AST, stmts: List[ast.stmt], ind_var: Optional[Tuple[str, ir.Type]] = None,
                  make_args: bool = False) -> BlockInOut:
    with self.visit_region() as (outer_scope, _):
        block = ir.Block()
        if ind_var is not None:
            name, ir_type = ind_var
            arg = block.add_argument(ir_type)
            self.scope.save(name, PlainValue(arg))
        global_builder.get_ir_builder().set_insertion_point_to_start(block)
        self.visit_statements(stmts)
        for name in self.scope.redefined:
            old_value = outer_scope.lookup(name)
            new_value = self.scope.lookup(name)
            if type(old_value) is not type(new_value):
                self.raise_unsupported(
                    node, f"'{name}' was re-assigned to an object with different type: "
                    f"initial type is {old_value.__class__.__name__}, new type is {new_value.__class__.__name__}")
        _, init_handles = self.mat_ir_values(outer_scope.lookup(name) for name in self.scope.redefined)
        if make_args:
            for handle in init_handles:
                arg = block.add_argument(handle.get_type())
                handle.replace_uses_in_block(block, arg)
        yield_values, yield_handles = self.mat_ir_values(self.scope.lookup(name) for name in self.scope.redefined)
        return BlockInOut(
            block=block,
            init_handles=dict(zip(self.scope.redefined, init_handles)),
            yield_values=dict(zip(self.scope.redefined, yield_values)),
            yield_handles=dict(zip(self.scope.redefined, yield_handles)),
        )

def dereference_name(self, name: str) -> Optional[Any]:
    return self.scope.lookup(name)

